
// Import ---------------------------------------

import { useEffect, useState } from "react";

// Component ------------------------------------

function CourtesyPhone( { setBond } ) {

    // States -------------------------

    const [ burrowedPhone, setBurrowedPhone ] = useState(0);
    const [ burrowedCharger, setBurrowedCharger ] = useState(0);

    // Data ---------------------------

    const itemList = [
        {id: 1, type: 'phone', name: 'iphone 10', bond: 275},
        {id: 2, type: 'phone', name: 'iphone 14', bond: 300},
        {id: 3, type: 'phone', name: 'iphone 16', bond: 500},
        {id: 4, type: 'phone', name: 'samsung galaxy', bond: 200},
        {id: 5, type: 'phone', name: 'nokia', bond: 150},
        {id: 6, type: 'phone', name: 'xiaomi', bond: 100},
        {id: 7, type: 'charger', name: 'iphone charger', bond: 45},
        {id: 8, type: 'charger', name: 'samsung charger', bond: 30},
        {id: 9, type: 'charger', name: 'nokia charger', bond: 25},
        {id: 10, type: 'charger', name: 'xiaomi', bond: 25}
    ];

    // Functions/Methods --------------

    const addPhone = selectedItem => {
        selectedItem === 'none' ? setBurrowedPhone(0) : setBurrowedPhone(Number(selectedItem))
    };

    const addCharger = selectedItem => {
        selectedItem === 'none' ? setBurrowedCharger(0) : setBurrowedCharger(Number(selectedItem))
    };

    useEffect(() => {
        let price = 0
        if (burrowedPhone) { price += itemList.filter( item => {return item.id === burrowedPhone} )[0].bond }
        if (burrowedCharger) { price += itemList.filter( item => {return item.id === burrowedCharger} )[0].bond }
        setBond( price )
    }, [ burrowedPhone, burrowedCharger ])

    // Return UI ----------------------

    return (
        <>
        <h2>Courtesy Phone</h2>
        {/*Phone item types*/}
        <div className="row p-1">
            <div className="col-12 col-lg-4">
                <label className="col-form-label">Choose a Phone</label>
            </div>
            <div className="col-12 col-lg-8">
                <select className="form-select" name="courtesy_phone" onChange={ e => addPhone(e.target.value) }>
                    <option value="none" defaultValue>None</option>
                    {
                        itemList.filter( item =>
                            item.type === 'phone'
                        ).map( item => { 
                            return ( <option key={item.id} value={item.id}>{item.name}</option> )
                        })
                    }
                </select>
            </div>
        </div>

        {/*Charger item types*/}
        <div className="row p-1">
            <div className="col-12 col-lg-4">
                <label className="col-form-label">Choose a Charger</label>
            </div>
            <div className="col-12 col-lg-8">
                <select className="form-select" name="courtesy_charger" onChange={ e => addCharger(e.target.value) }>
                    <option value="none" defaultValue>None</option>
                    {
                        itemList.filter( item =>
                            item.type === 'charger'
                        ).map( item => { 
                            return ( <option key={item.id} value={item.id}>{item.name}</option> )
                        })
                    }
                </select>
            </div>
        </div>

        {/*Table of added Courtesy items*/}
        <h4 className='ms-4 mt-2'>Borrow items</h4>
        <div className="row mt-2 ms-3 me-3 bg-white">
        <table className="table table-bordered" >
        <thead><tr>
            <th>Item</th>
            <th>Cost</th>
        </tr></thead>
        {
            /* Display Burrowed Items */
            burrowedPhone === 0 ? (null) : (
                <tbody><tr>
                    <td>{ itemList.filter( item => {return item.id === burrowedPhone} )[0].name }</td>
                    <td>{ itemList.filter( item => {return item.id === burrowedPhone} )[0].bond }</td>
                </tr></tbody>
            )
        }{
            burrowedCharger === 0 ? (null) : (
                <tbody><tr>
                    <td>{ itemList.filter( item => {return item.id === burrowedCharger} )[0].name }</td>
                    <td>{ itemList.filter( item => {return item.id === burrowedCharger} )[0].bond }</td>
                </tr></tbody>
            )
        }
        </table>
        </div>
        </>
    );
};

// Export Component -----------------------------

export default CourtesyPhone;

